  create(name: string): SnapshotPolicy { return this.map.get(name)!.call(null); }
}
class AfterNEventsPolicy { constructor(private n: number) {} shouldSnapshot(state: any, batch: any[]) { return batch.length >= this.n; } name() { return `after-${this.n}-events`; } }
